        *cell_temps[i] = lv_label_create(*cell_panels[i]);
        lv_label_set_text(*cell_temps[i], hour_temps[i]);
        lv_obj_set_style_text_color(*cell_temps[i], UI_COLOR_INK1, LV_PART_MAIN | LV_STATE_DEFAULT);
