    ui_panel_statusbar = lv_obj_create(ui_scr_home);
    lv_obj_set_width(ui_panel_statusbar, 1024);
    lv_obj_set_height(ui_panel_statusbar, 24);
    lv_obj_remove_flag(ui_panel_statusbar, LV_OBJ_FLAG_SCROLLABLE); /// Flags
