    lv_obj_set_style_border_width(ui_panel_statusbar, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_bg_color(ui_panel_statusbar, UI_COLOR_BG0, LV_PART_MAIN | LV_STATE_DEFAULT);
