    lv_obj_set_style_pad_right(ui_panel_statusbar, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_set_style_pad_top(ui_panel_statusbar, 0, LV_PART_MAIN | LV_STATE_DEFAULT);
